SELECT "nct", "author", "year", "pubmed_id", "trial_phase", "treatment_regimen", "control_regimen", "class_of_ici", "name_of_ici", "type_of_combination", "monotherapy_combination" FROM public."clinical_trials" WHERE "trial_phase" = 'Phase 3' AND "cancer_type" = 'Multiple Myeloma' AND "class_of_ici" = 'PD1' AND "type_of_combination" IS NOT NULL ORDER BY "year" DESC;